@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const type=document.querySelector('#configuration-type'),scope=document.querySelector('#scope-type'),builder=document.querySelector('#break-builder'),json=document.querySelector('#break-options-json');let breaks=[{key:'meal',label:'Meal Break',duration_minutes:40,active:true},{key:'second',label:'Second Break',duration_minutes:30,active:true},{key:'meeting',label:'Meeting',duration_minutes:null,active:true},{key:'downtime',label:'Downtime',duration_minutes:null,active:true}];const slug=s=>s.toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');function renderBreaks(){builder.innerHTML=breaks.map((item,i)=>`<div class="break-builder-row"><label>Break name<input data-break-label="${i}" value="${item.label.replace(/"/g,'&quot;')}" placeholder="e.g. Meal Break"></label><label>Minutes <span>(optional)</span><input type="number" min="1" data-break-duration="${i}" value="${item.duration_minutes??''}" placeholder="No limit"></label><label class="check break-active"><input type="checkbox" data-break-active="${i}" ${item.active?'checked':''}> Active</label><button type="button" class="remove-break" data-remove-break="${i}" aria-label="Remove break">×</button></div>`).join('');syncBreakJson()}function syncBreakJson(){json.value=JSON.stringify(breaks.map(item=>({key:item.key||slug(item.label),label:item.label,duration_minutes:item.duration_minutes?Number(item.duration_minutes):null,active:Boolean(item.active)})))}builder.addEventListener('input',e=>{const i=Number(e.target.dataset.breakLabel??e.target.dataset.breakDuration);if(Number.isNaN(i))return;if(e.target.dataset.breakLabel!==undefined){breaks[i].label=e.target.value;breaks[i].key=slug(e.target.value)}else breaks[i].duration_minutes=e.target.value||null;syncBreakJson()});builder.addEventListener('change',e=>{if(e.target.dataset.breakActive!==undefined){breaks[Number(e.target.dataset.breakActive)].active=e.target.checked;syncBreakJson()}});builder.addEventListener('click',e=>{if(e.target.dataset.removeBreak!==undefined){breaks.splice(Number(e.target.dataset.removeBreak),1);renderBreaks()}});document.querySelector('#add-break').addEventListener('click',()=>{breaks.push({key:'',label:'New Break',duration_minutes:null,active:true});renderBreaks()});function sync(){document.querySelectorAll('[data-config-fields]').forEach(section=>{const active=section.dataset.configFields===type.value;section.hidden=!active;section.querySelectorAll('input,select,textarea,button').forEach(field=>field.disabled=!active)});document.querySelector('#department-scope').hidden=scope.value!=='department';document.querySelector('#employee-scope').hidden=scope.value!=='employee';document.querySelectorAll('[data-scope-list]').forEach(list=>{const active=list.dataset.scopeList===scope.value;list.name=active?'scope_id':'';list.disabled=!active});syncBreakJson()}type.addEventListener('change',sync);scope.addEventListener('change',sync);renderBreaks();sync()});</script>@endpush
